function fmt(key:string,value:any){if(value===null||value===undefined||value==='')return '—';if(key==='outs_recorded')return `${Math.floor(Number(value)/3)}.${Number(value)%3}`;if(['iso','babip','avg','obp','slg','ops','pct'].includes(key))return Number(value).toFixed(3).replace(/^0\./,'.');if(['kPct','bbPct','kMinusBbPct','k9','bb9','hr9','kbb','era','whip'].includes(key))return Number(value).toFixed(2);if(['division_rank','league_rank','mlb_rank'].includes(key))return String(Number(value));return String(value);}
function go(path:string){window.location.hash=path;window.scrollTo({top:0});}
function useRoute(){const read=()=>(window.location.hash.slice(1).split('?')[0].replace(/^player\//,'/players/'))||'/teams';const [route,setRoute]=useState(read);useEffect(()=>{const f=()=>setRoute(read());window.addEventListener('hashchange',f);return()=>window.removeEventListener('hashchange',f);},[]);return route;}
const dateISO=()=>new Date().toLocaleDateString('en-CA');
function Source({data,children}:{data:Row|null;children?:React.ReactNode}){return <div className={'source-note '+(data?.stale?'warning':'')}><span>{children||data?.source}</span>{data?.fetched_at&&<small>{data.stale?'Cached data · refresh unavailable · ':'Updated '}{new Date(data.fetched_at).toLocaleString()}</small>}</div>;}
function Coverage({data}:{data:Row|null}){if(!data)return null;return <div className={'coverage '+(data.complete?'complete':'')}><span className="dot"/><strong>{data.complete?'Game-log coverage verified':'Game logs still importing'}</strong><span>{data.imported_games.toLocaleString()} / {data.expected_games.toLocaleString()} played games have local box scores.</span></div>;}
function Status({state,onRetry}:{state:{loading:boolean;error:string;data?:any};onRetry:()=>void}){return <>{state.loading&&!state.data&&<div className="empty" role="status">Loading MLB data…</div>}{state.error&&<div className="error" role="alert">{state.error}<button onClick={onRetry}>Retry</button></div>}</>;}
function Empty({text='No data for this selection.'}:{text?:string}){return <p className="empty">{text}</p>;}
function StatCards({stats,discipline}:{stats:Row;discipline:string}){const keys=discipline==='batting'?['plateAppearances','homeRuns','avg','obp','slg','ops']:['outs_recorded','wins','losses','era','whip','strikeOuts'];return <div className="stat-cards">{keys.map(key=><div key={key}><span>{labels[key]}</span><strong>{fmt(key,stats?.[key])}</strong></div>)}</div>;}
