  const [minPA,setMinPA]=useSaved('players:minPA',''),[minIP,setMinIP]=useSaved('players:minIP',''),[minAge,setMinAge]=useSaved('players:minAge',''),[maxAge,setMaxAge]=useSaved('players:maxAge',''),[pitcherRole,setPitcherRole]=useSaved('players:pitcherRole','all');
  useEffect(()=>{const timer=setTimeout(()=>{setQuery(search);setOffset(0);},250);return()=>clearTimeout(timer);},[search]);
  useEffect(()=>{setOffset(0);if(gameType!=='R')setQualified(false);},[season,gameType]);
  const state=useData('/explore/players?'+params({season,game_type:gameType,discipline,qualified:qualified&&gameType==='R',q:query,team_id:team,position,sort,direction,offset,limit:50,min_pa:discipline==='batting'?minPA:0,min_ip:discipline==='pitching'?minIP:0,min_age:minAge,max_age:maxAge,pitcher_role:discipline==='pitching'?pitcherRole:'all'}),revision);
  const coverage=useData('/explore/coverage?'+params({season,game_type:gameType}));
  const changeDiscipline=(value:string)=>{setDiscipline(value);setSort(value==='batting'?'ops':'era');setDirection(value==='batting'?'desc':'asc');setPosition('');setOffset(0);};
  const changeSort=(key:string)=>{setDirection(sort===key?(direction==='desc'?'asc':'desc'):(['full_name','team_name','position','era','whip','bb9','hr9'].includes(key)||(key==='bbPct'&&discipline==='pitching')||(key==='kPct'&&discipline==='batting'))?'asc':'desc');setSort(key);setOffset(0);};
  return <><Coverage data={coverage.data}/><section className="panel"><div className="section-head"><div><h2>{leaderboard?'Season leaderboards':'Player directory'}</h2><span>{state.data?.total?.toLocaleString()??'…'} players · {season} {gameTypes[gameType]?.toLowerCase()}</span></div><div className="segmented"><button className={discipline==='batting'?'selected':''} onClick={()=>changeDiscipline('batting')}>Batters</button><button className={discipline==='pitching'?'selected':''} onClick={()=>changeDiscipline('pitching')}>Pitchers</button></div></div><div className="filters"><label>Player<input aria-label="Search players" placeholder="Search player name" value={search} onChange={e=>setSearch(e.target.value)}/></label><label>Season team<select value={team} onChange={e=>{setTeam(e.target.value);setOffset(0);}}><option value="">All teams</option>{teams.map(t=><option value={t.id} key={t.id}>{t.name}</option>)}</select></label><label>Position<select value={position} onChange={e=>{setPosition(e.target.value);setOffset(0);}}><option value="">All positions</option>{['P','C','1B','2B','3B','SS','LF','CF','RF','DH','TWP'].map(p=><option key={p}>{p}</option>)}</select></label><label className="check-label"><input type="checkbox" checked={qualified&&gameType==='R'} disabled={gameType!=='R'} onChange={e=>{setQualified(e.target.checked);setOffset(0);}}/>Qualified players only</label><button className="secondary" onClick={()=>setRevision(x=>x+1)}>Refresh</button></div><div className="filters advanced-filters"><label>Minimum {discipline==='batting'?'plate appearances':'innings pitched'}<input type="number" min="0" step="1" value={discipline==='batting'?minPA:minIP} onChange={e=>{(discipline==='batting'?setMinPA:setMinIP)(e.target.value);setOffset(0);}}/></label><label>Minimum age<input type="number" min="0" value={minAge} onChange={e=>{setMinAge(e.target.value);setOffset(0);}}/></label><label>Maximum age<input type="number" min="0" value={maxAge} onChange={e=>{setMaxAge(e.target.value);setOffset(0);}}/></label>{discipline==='pitching'&&<label>Pitcher role<select value={pitcherRole} onChange={e=>{setPitcherRole(e.target.value);setOffset(0);}}><option value="all">All pitchers</option><option value="starter">Mostly starts (50%+)</option><option value="reliever">Mostly relief (under 50%)</option></select></label>}<button className="text-button" onClick={()=>{setMinPA('');setMinIP('');setMinAge('');setMaxAge('');setPitcherRole('all');setTeam('');setPosition('');setSearch('');setQualified(leaderboard);setOffset(0);}}>Reset filters</button><button className="secondary" onClick={()=>go('/compare')}>Open comparison →</button></div><p className="table-help">Enter innings minimums as whole innings. Pitcher role is based on the fraction of appearances that were starts.</p><p className="table-help">Click a column to rank players. {qualified?'MLB’s official qualification pool is applied.':'All sample sizes are included.'} Qualification is available for the regular season.</p><Status state={state} onRetry={()=>setRevision(x=>x+1)}/>{state.data&&<><StatTable rows={state.data.items} discipline={discipline} sort={sort} onSort={changeSort}/><Pager offset={offset} total={state.data.total} onChange={setOffset}/><Source data={state.data}>{state.data.source}. {state.data.note}</Source></>}</section></>;
